fn fetch_all_delay(keys: [str]) -> [int]:
    return parallel([
        lambda: delay(k) for k in keys
    ])

fn largest_price(keys: [str]) -> str:
    return parallel([
        lambda: keys[i] if price(keys[i]) > price(keys[j]) else keys[j]
        for i in range(len(keys))
        for j in range(i + 1, len(keys))
    ]).first()

fn largest_stock(keys: [str]) -> str:
    return parallel([
        lambda: keys[i] if stock(keys[i]) > stock(keys[j]) else keys[j]
        for i in range(len(keys))
        for j in range(i + 1, len(keys))
    ]).last()

fn largest_weight(keys: [str]) -> str:
    return parallel([
        lambda: (ord(k[0]) * 3 + len(k), k) for k in keys
    ]).max().2

fn count_even_price(keys: [str]) -> int:
    return parallel([
        lambda: price(k) % 2 == 0 for k in keys
    ]).count(True)

fn count_even_stock(keys: [str]) -> int:
    return parallel([
        lambda: stock(k) % 2 == 0 for k in keys
    ]).count(True)

fn count_even_weight(keys: [str]) -> int:
    return parallel([
        lambda: weight(k) % 2 == 0 for k in keys
    ]).count(True)

fn combined_price(keys: [str]) -> [int]:
    return parallel([
        lambda: price(key) + stock(key) for key in keys
    ])

fn combined_stock(keys: [str]) -> [int]:
    return parallel([
        lambda: stock(keys[i]) for i in range(len(keys))
    ])

fn combined_score(keys: [str]) -> [int]:
    return parallel([
        lambda: score(keys[0]),
        lambda: score(keys[1]),
        lambda: weight(keys[0]) + weight(keys[1])
    ])

fn combined_delay(keys: [str]) -> [int]:
    return parallel([
        lambda: delay(key),
        lambda: price(key)
        for key in keys
    ])

fn above_price(keys: [str], limit: int) -> [str]:
    return parallel([
        lambda: price(key) > limit for key in keys
    ]).map(lambda: key for key, _ in parallel([
        lambda: (price(key), key) for key in keys
    ])).filter(lambda: _ > limit).collect()

fn above_stock(keys: [str], limit: int) -> [str]:
    return parallel([
        lambda: keys[i] if stock(keys[i]) > limit else None
        for i in range(len(keys))
    ]).filter(|x| x is not None).map(|x| x!).sort()

fn above_score(keys: [str], limit: int) -> [str]:
    return parallel([
        lambda: score(k) > limit for k in keys
    ]).map(lambda: k for k, _ in if _).collect()

fn above_weight(keys: [str], limit: int) -> [str]:
    return parallel([
        lambda: weight(key) > limit for key in keys
    ]).map(lambda: key for key, _ in zip(keys, _))

fn above_delay(keys: [str], limit: int) -> [str]:
    return parallel([
        lambda: keys[i] if delay(keys[i]) > limit else None
        for i in range(len(keys))
    ]).filter(|x| x is not None).map(|x| x!).sort()
